import re
from collections import Counter

text = open('/tmp/exhibitors_from_wechat.txt', 'rb').read().decode('utf-8', errors='replace')
lines = text.split('\n')

exhibitors = []
current_hall = None

for line in lines:
    ls = line.strip()
    if '馆' in ls and '==' in ls:
        m = re.search(r'(E\d馆|W\d馆|N\d馆)', ls)
        if m:
            current_hall = m.group(1)
            continue
    if '|' in ls and current_hall:
        parts = ls.split('|')
        if len(parts) >= 2:
            name = parts[0].strip()
            booth = parts[1].strip()
            if name and booth and len(name) > 2:
                exhibitors.append({'name': name, 'booth': booth, 'hall': current_hall})

print(f"Total exhibitors: {len(exhibitors)}")

# Count by hall
hall_counts = Counter(e['hall'] for e in exhibitors)
print("\n=== 展商数量统计 ===")
for hall in sorted(hall_counts.keys()):
    print(f"  {hall}: {hall_counts[hall]}家")

# Search terms
terms = [
    ('哈希','Hach'), ('HACH','Hach'), ('威立雅','Veolia'),
    ('E+H','E+H'), ('恩德斯','E+H'), ('赛莱默','Xylem'),
    ('赛默飞','Thermo'), ('ABB','ABB'), ('西门子','Siemens'),
    ('横河','Yokogawa'), ('梅思安','MSA'),
]

found = {}
for e in exhibitors:
    n = e['name'].upper()
    for term, brand in terms:
        if term.upper() in n or term in e['name']:
            if brand not in found:
                found[brand] = []
            found[brand].append(e)

print("\n=== 关键展商 ===")
for brand in sorted(found.keys()):
    print(f"\n【{brand}】")
    for e in found[brand]:
        print(f"  {e['name']} | {e['booth']} ({e['hall']})")
if not found:
    print("未找到")

print("\n\n=== E4馆 (前30) ===")
e4 = [e for e in exhibitors if e['hall'] == 'E4馆']
print(f"E4馆共 {len(e4)} 家")
for e in e4[:30]:
    print(f"  {e['name']} | {e['booth']}")

print("\n\n=== E1馆监测相关 ===")
monitoring = ['监测','仪表','传感','控制','分析','检测','仪器','测量']
e1 = [e for e in exhibitors if e['hall'] == 'E1馆']
e1m = [e for e in e1 if any(k in e['name'] for k in monitoring)]
print(f"E1馆监测相关 {len(e1m)} 家")
for e in e1m[:20]:
    print(f"  {e['name']} | {e['booth']}")"}

